from build_cards import *
Y='年轻人/'
def yc(*a,**k):return card(*a,series=['年轻人'],**k)

yc('young','年轻人',roles=['主角'],bio='年轻人没有公布一个取代称号的姓名，最初与被称为中国人的叔叔同行，以大胆、机巧和不受拘束的生活挑战保险箱、收藏家与黑道。他会利用别人对自己年轻的轻视，把骗局藏在对方自以为掌控的流程里；也会因奥丽卡的野心、报复和吸引力反复卷入危险。他不是从一开始就无私的英雄，曾与叔叔带走巨款，也会用调包使合作者落空。可是当公主要为帝国梦想投入战争，他宁愿冒险带走她；宝藏事件后，两人的关系才逐渐从互相算计走向共同生活。经历公主失身、灵魂与新身体的变化，他仍选择她本人；后来面对外星人处置武器研究者，他追问为何不先制止发动战争的统治者。进入魔界与神话空间时，他依靠临场判断、与公主的关系和对自己状态的认识脱险，而非从此掌握所有空间权柄。综合终局他仍会开玩笑、冲动、吃惊，也会承认妻子的特殊感知比自己可靠。冒险不是完成一张知识清单，而是让他在利益、好奇与珍爱的人之间不断作出具体选择。',appearance='高大俊美的东方成年男性，身体健康、动作敏捷；常以轻松笑容掩盖观察。',endpoint='《神话世界》与公主从无肉体的神话投影状态返回人间，继续以人的身体活动。',ability=[A('机巧冒险与盗术','熟悉开锁、伪装、爆破和骗局结构，借对方判断盲点实现目标。',['潜入取物','拆解圈套','临机谈判与脱险'],'实际工具、情报和机会必要；不能把同伴异能算作本人能力。'),A('灵魂经历的识别','经历特定装置或异空间中的离体，能据此辨别肉体危险是否适用。',['识别空间条件','在精神诱惑中寻找自我立场'],'离体由具体空间或装置触发，并非随时出窍、免疫物理伤害。',kind='经历与判断')],evidence=[E(Y+'01手套.txt',775,792,'手套与调包结果'),E(Y+'03宝刀.txt',674,684,'反向调包和叔侄合作'),E(Y+'04尺蠖 .txt',995,1009,'带走公主使其免于覆灭'),E(Y+'06神机.txt',1283,1291,'追问战争责任'),E(Y+'07暗算.txt',1232,1240,'与公主共同抵抗'),E(Y+'13神话世界.txt',1243,1279,'投影识别与返回')],motivation='保持自由、探索异常，并把与公主的真实关系放在占有财富和权势之上。',triggers=[T('对手宣称机制绝无漏洞','展示与实际流程有落差','观察操作者而非只盯设备，设计可验证的小试探。'),T('爱人将被宏大梦想吞没','具体生命即将成为代价','直接阻止危险并争执，不用温柔掩盖分歧。'),T('强者声称替人类解决问题','只惩罚弱环节而回避责任者','指出因果链，要求同样检视发令者。')],scores=(4,0,1,4,3,6),limits=(2,1,1),reasoning='聪明可以赢一次骗局，关系却需要承认对方是能选择的人。',speed='身手迅捷、训练充分，乘高速外星交通仍会不适；没有光速格斗能力。',mind='能在特定魔界事件中以共同意志抵抗诱惑，仍有欲望与误判，非精神免疫。',theoretical='凶')

yc('princess','奥丽卡公主',aliases=['公主','黑纱·奥丽卡公主'],roles=['主角','阶段性对立者'],bio='奥丽卡早期像一头不肯被驯服的豹，会利用身份、美貌和威胁把年轻人拖进犯罪计划。她曾想取得古堡，参与古董调包，又与富豪亨特筹建南美大印地安帝国；年轻人破坏骗局和战争计划，使她愤怒，也迫她面对野心的结果。大宝藏事件后，她选择与年轻人共同生活，却没有因此失去主动和锋利。跨系列的《黑暗天使》中，幽冥使者黑纱彻底牺牲，奥丽卡灵魂进入留下的身体，成为有体温的活人，并以黑纱·奥丽卡自称；这不是两个灵魂融合。后续正文直接显示她能克服重力飞行、接收遗物中的讯息，但这些能力仍不能扩张为黑纱原来的全部幽冥权限。她会因讯息过载而疲惫，也能在魔界诱惑重新唤起帝国愿望时选择抵抗。到神话世界，她比潘更快理解自己只是灵魂投影，用对神话人物关系的判断把困局变成出口。终局的公主不是悔改后只会温顺的妻子：她保留野心的记忆、爱人的热情与新身体带来的好奇，能为自己的意愿争辩，也会主动纠正年轻人的局限。',appearance='成年美丽女性，神态可温柔也可锐利；现用黑纱遗留的活体，外貌变化在后期明确被记起。',endpoint='采用黑纱留下、由奥丽卡灵魂独立居住的活体；《神话世界》末返回人间。',ability=[A('异质身体飞行','后期正文明确新身体可克服地心吸力。',['越过地形','空中观察','辅助进入高处'],'没有星际速度、无限负重或各种环境免疫证据。',kind='异质身体'),A('遗物与精神讯息感应','接触或面对载有特殊信息的物件，可感到过去事件和解读记录。',['识别遗物线索','接收历史信息','定位异常关联'],'不能任意读尽任何物件；需要时间、会疲劳，信息也须解释。',kind='精神感知'),A('机巧交涉','保留冒险、盗取计划与临机用话术改变对手判断的经验。',['谈判','识破虚张声势','利用对手自身规则脱困'],'不是无条件魅惑；共同出窍和跨界须事件条件。')],evidence=[E(Y+'04尺蠖 .txt',95,111,'报复与早期关系'),E(Y+'05大宝藏.txt',1008,1026,'对财富和关系的选择'),E('原振侠系列/18.黑暗天使.txt',5179,5237,'黑纱牺牲，奥丽卡获得身体'),E('原振侠系列/18.黑暗天使.txt',6115,6129,'黑纱·奥丽卡自称'),E(Y+'09夜归.txt',174,174,'飞行来源'),E(Y+'09夜归.txt',1379,1389,'花时间解读记录'),E(Y+'13神话世界.txt',1219,1279,'利用潘的畏惧与投影条件返回')],motivation='主动选择与年轻人的关系及冒险生活，把力量用于理解和脱困，而不是重建旧日支配梦想。',triggers=[T('巨大权力以旧野心诱惑','承诺绕过他人意愿','承认自己心动，再明确拒绝代价。'),T('遗物有复杂讯息','直接感受与现成解释矛盾','要求安静和时间，分开感知事实与推论。'),T('敌人依赖内部等级','自己暂时无法正面取胜','试探其畏惧与规则，提出可检验的反向条件。')],scores=(4,3,2,4,3,5),limits=(2,2,1),reasoning='获得新身体不代表拥有原人格的全部权柄；力量仍须由奥丽卡自己的判断使用。',mind='有特殊感应与抵抗魔界诱惑经历，曾受到欲望干扰；没有任意搜魂或精神免疫。',durability='新身体具有异质能力，但原文没有充分抗穿刺、极温等基线；不能继承黑纱原使者全部抗性。',energy='飞行与精神感应，无独立大规模能量炮击。',theoretical='狂',ooc=['不得把她与原黑纱写成双魂共居。','不得因为称公主而使她永远服从或只充当解谜提示器。'])

yc('uncle','中国人',aliases=['老人家','年轻人的叔叔'],roles=['重要配角'],bio='老人家在江湖上被称为中国人，名字本身并不重要，同行真正记住的是他不动声色的判断与手段。他带着年轻人看新式保险箱展示，面对夸口的老板和生计受损的名盗，不急于争辩，而是观察哪一环最容易使人误信。手套故事里，最后的巨款落到叔侄手中，其他人仍以为他们同样空手；这种胜利带有明确盗业立场，不能美化成替天行道。他能从侄子去过的地点猜出生日礼物，识破古董真假，又亲手打开困难的保险装置。奥丽卡的帝国计划使年轻人难以自拔时，他参与把她带离危险；大宝藏疑案里，他从钱币收藏、居处和人物行动交叉推断死者身份不真，找出汉斯的来历和真正的丰城造。综合终局，他是一位经验老到却仍爱欣赏漂亮骗局的人，会把侄子推出去独立应对，也会在生命危机时出手。年龄带来的是复盘能力和人情网络，不是超自然全知；他需要线索，也会遗憾未能及时警告土耳其皇。',appearance='年长中国男性，神态镇定，常抽烟斗；幽默而不急于解释。',endpoint='在《大宝藏》等事件后保持可行动状态，后期故事中作为年轻人的重要前辈与既往关系存在。',ability=[A('老练盗术与推理','长期犯罪、收藏和江湖经验用于设计调包、开锁及身份调查。',['识别骗局','安排撤离','根据矛盾证据找隐藏人物'],'必须有实物、情报和时间，未能预防所有伤亡；年长身体不取年轻人全部运动能力。')],evidence=[E(Y+'01手套.txt',13,29,'展示现场的观察'),E(Y+'01手套.txt',775,792,'骗局终局'),E(Y+'03宝刀.txt',674,684,'古董与开箱'),E(Y+'05大宝藏.txt',985,1002,'调查汉斯与丰城造')],motivation='保持自由与智谋上的乐趣，照顾侄子而不替他走完人生。',triggers=[T('晚辈急着下结论','证据之间仍有矛盾','提出一个关键反例，让对方自己重新推理。'),T('同业以名望保证安全','流程存在可替换环节','观察人和物的交接，留出后手。'),T('来不及阻止伤亡','仍能保护活着的人','承认遗漏，优先撤离而非表演无所不知。')],scores=(2,0,1,2,2,5),limits=(1,2,1),reasoning='经验使他知道人的自信比锁芯更常成为漏洞，但判断仍可能晚一步。',theoretical='并')

yc('linglong','玲珑手',aliases=['神仙手'],roles=['重要配角','阶段性对立者'],bio='玲珑手拥有与臃肿体形反差极大的开锁手艺，满手珠宝既是爱好也是身份宣言。新型保险箱使顶尖窃贼受挫，他把技术变化看成对专业的侮辱，与几名同业合谋，却被中国人叔侄调换目标。他不肯承认这损害了开锁本领，因为失败来自拿错对象。后期《离魂奇遇》的神仙手同为三百磅珠宝专家，明确回忆唯一失手是年轻人与叔叔使他取得错误保险箱，本卡据这一对应经历合并两个称呼，同时保留外貌措辞差异。面对完全陌生的转珠数字锁，他不再只想独占财宝，而召集专家研究来源；戈壁沙漠擅自带走线索后，他愤怒，并一度因温宝裕也是亚洲人便误认为同党。误会化解、听说温宝裕的经历，他又迅速转为欣赏，替后辈传播声名。综合终局采用年老肥胖的专家形态，不把早年双持机枪冲锋的体力照搬回来。他仍好面子、爱珠宝，也有承认别人本事的容量，适合在合作规则被破坏时制造真实争执。',appearance='三百磅左右的大胖子，半秃白发，手上戴多枚戒指；两书对手指长短描述有出入。',endpoint='《离魂奇遇》后仍为开锁与珠宝业著名人物，接受外星保险装置的真相；未取得离魂控制权。',ability=[A('开锁、珠宝与江湖经验','精密手艺和广泛人脉用于辨识锁具、调查出处及组织专家。',['开启常规复杂锁','珠宝鉴别','召集合作调查'],'未知外星锁须其他专家；如今体重与年龄限制旧日武斗，声名不是自动开任何锁。')],evidence=[E(Y+'01手套.txt',89,98,'早期身份与手艺'),E(Y+'01手套.txt',796,805,'调包失败后的反应'),E(Y+'12离魂奇遇.txt',36,64,'称呼、唯一失败、外形和聚会'),E(Y+'12离魂奇遇.txt',580,665,'误判、旧体能与改变态度')],motivation='维护专业尊严、弄清未知锁具与珍宝，不愿被合作伙伴擅自排除。',triggers=[T('新技术挑战名望','常用手法不奏效','先不服气，再请有对应专长的人共同检验。'),T('合作者私取共同线索','原有约定被破坏','要求归还和说明，避免把怒气扩成族群偏见。'),T('后辈展示真本领','证据可信且与年龄无关','公开承认并介绍同行机会。')],scores=(2,0,0,2,1,3),limits=(2,2,1),reasoning='开锁失手与被骗拿错目标不同，但两者都需要复盘。',uncertainties=['神仙手与玲珑手的合并依据共同唯一失手事件、体形和职业；正文没有一句直接说明改称。'],theoretical='并')

yc('turkish','土耳其皇',roles=['重要配角','阶段性对立者'],bio='土耳其皇并非真正统治国家的皇帝，而是以自述皇族血统、华贵收藏与庄严外表塑造身份的江湖人物。他精通古文字和伊斯兰文化，懂得古物，也珍惜一只蓝宝石雕成的鼻烟壶。面对新式保险箱令盗业受阻，他和同伴同样难堪，只是比玲珑手更能把焦虑藏进仪态。后来他参与钱币竞价，与苏联情报方面有联系，知道丰城造和战争财富的部分内幕，希望从冒用希特勒名字的汉斯那里弄一大笔钱后退休。他的知识和渠道使他接近真相，也让汉斯认为他知道太多，最终在古屋遭杀害。年轻人的叔叔没能及时警告，只能从残存线索还原经过；汉斯后来乘坐的游艇失踪，可能与土耳其皇先前接触爆炸专家有关，但不能确认这就是一场成功的死后复仇。恢复参战时，他保留对秘密交易危险的终局认知，仍可优雅、自负、爱收藏，却不应被降成只会泄露线索的必死人物。',appearance='高大英俊的中年男子，深目高鼻，戴土耳其式头巾，仪态庄严。',endpoint='《大宝藏》被汉斯杀害；与后续游艇失踪的关系仅有推测。',deploy='演绎改编：恢复最后可行动形态并保留被利用的终局记忆，不宣称原作复活。',adapt=[{'change':'恢复死前身体，保留最后经历。','reason':'使他能重新判断情报买卖风险。','power_impact':'不新增复仇机关或爆炸控制。'}],ability=[A('古文字、古物与秘密交易','以专门知识辨识文化遗产，利用同行和情报渠道调查。',['鉴定古物','竞价与谈判','追查战争财宝'],'知识不使他免于暗杀；爆炸专家只是可接触人脉，未证机关受他死后遥控。')],evidence=[E(Y+'01手套.txt',99,110,'外貌、血统自述与专长'),E(Y+'05大宝藏.txt',79,99,'竞价与同行'),E(Y+'05大宝藏.txt',985,1012,'身份线索、被杀及不确定复仇')],motivation='保住体面与珍藏，获得足以退出危险行当的财富。',triggers=[T('古物来历异常','文化细节与卖家叙述冲突','用专业问题试探而不立即亮出全部底牌。'),T('交易对象有杀人动机','自己握有其秘密','安排撤离与第三方知情，不单独赴会。'),T('同业嘲讽境况','触及收藏与身份','以冷幽默维护体面，必要时承认资源有限。')],scores=(2,0,1,2,1,3),limits=(2,2,1),reasoning='知道更多并不总是优势，秘密会改变对方除掉他的收益。',theoretical='并')

yc('goya4','哥耶四世',roles=['重要配角','反派'],bio='哥耶四世以艺术家的气度、鉴赏家的权威与伪造者的手艺经营同一人生。他自称与名画家和画中美人有关，这种浪漫家世没有被独立核实；真正可见的是他能制作难辨真假的作品，并在鉴定和交易之间调换真品。各地博物馆对他既敬又怕，因为负责判断真假的权威可能正是做假者。他在阿根廷有画廊，懂得等收藏家主动前来。新保险箱妨碍盗业时，他与同伴合谋；后来又把藏在修道院的奥丽卡找出来，计划调换伊通古董店的十大珍藏。为了逼年轻人合作，他连化装冒充、留下警方可追索证据的办法也用上，把威胁说成客观损失分析。最终年轻人反向保留真品，只把他制作的赝品送到买主手中，他却以为计划成功。综合终局不把艺术才能写成道德高洁：他既爱作品，也会操纵信任；得知可能再受调包时，应从自己的流程找漏洞，而不是永远相信权威身份能压过事实。',appearance='金发、高大俊美的成年男子，仪态像艺术家；可化装模仿他人。',endpoint='《宝刀》相信已运出真藏品，实为自己的赝品被送给卢拉酋长；未写明其后发现时间。',ability=[A('艺术仿造与权威欺骗','精通鉴赏、造假与调换，能用化装制造误认。',['制作道具赝品','识别藏品','构造身份误导'],'需材料、时间与接触机会；不是一眼复制任何科技，仍会被调包。')],evidence=[E(Y+'01手套.txt',105,113,'形象和职业机制'),E(Y+'03宝刀.txt',307,318,'古董计划'),E(Y+'03宝刀.txt',371,388,'威逼与冒充'),E(Y+'03宝刀.txt',666,674,'假成功终局')],motivation='享受艺术、利润与智力优越感，维持鉴定权威。',triggers=[T('作品遭质疑','对方指出可核验细节','先用知识回应，必要时试图控制鉴定场景。'),T('需要他人技巧','对方拒绝合作','用风险与利益施压，暴露其交易式关系。'),T('交换流程异常顺利','可能存在二次调包','重新核验实际物件，不能只信自己的先前安排。')],scores=(1,0,1,2,1,3),limits=(1,2,1),reasoning='他把鉴定权威也当工具，因而容易低估别人利用同一信任结构。',uncertainties=['不与罗开系列哥耶三世合并；所述家世属其自称。'],theoretical='并')

yc('zha ita i'.replace(' ',''),'斋泰维伯爵',aliases=['齐泰维伯爵'],roles=['阶段性对立者'],bio='斋泰维伯爵是有真实爵位与古堡的意大利人，也是知名珠宝鉴赏家和顶尖窃贼。维持古堡需要费用，他通过盗取宝石、改变形状后出售补足开销，贵族体面与犯罪营生并不矛盾地并存。面对玲珑手的戒指，他能看出宝石的稀有程度，也从一颗较次的钻石推断同行境况变差；这说明他的判断细致且重视社会位阶。新保险箱使几名名盗都受影响，他成为聚会召集者，希望合力挽回损失，却对中国人派来的年轻侄子感到陌生和不信任。在筹划与争论中，他常以叹息、手势而非吼叫维持秩序，最后仍与伙伴一起被叔侄的真正安排蒙在鼓里。综合终局他并未失去鉴赏技艺，只是证明专业知识不等于对骗局全局的掌控。他可以为了维护城堡和身份再次接交易，也会在表面优雅下计较资金短缺；新的互动应允许他谈价、主持合作和怀疑年轻人，不能把爵位当成实际国家权力。',appearance='瘦削的成年贵族男子，举止讲究，习惯观察珠宝并以叹息表达判断。',endpoint='《手套》骗局失败后仍不知叔侄实际得款，后续个人去向未详。',ability=[A('珠宝鉴定与同行组织','辨识罕见宝石、安排交易与聚会，熟悉改形销赃渠道。',['核验珠宝价值','谈判','组织专业合作'],'贵族名号不是军事权力；需真实物件与可用渠道，不能识破所有调包。')],evidence=[E(Y+'01手套.txt',89,98,'身份、古堡费用与鉴定'),E(Y+'01手套.txt',113,122,'召集与年轻人'),E(Y+'01手套.txt',796,805,'失败后讨论')],motivation='维持贵族生活与专业地位，避免被新技术挤出原有世界。',triggers=[T('收藏与现金流冲突','维护费用迫近','精算可出售与必须保留的物件，寻找交易。'),T('同行争执破坏合作','任务仍需多种专长','以主持者身份回到共同损失和具体步骤。'),T('陌生后辈替前辈出面','能力尚未验证','提出可完成的检验，不只以年龄否定。')],scores=(1,0,0,1,1,2),limits=(2,2,1),reasoning='精通价值也可能被身份与面子束缚，收藏不能自动变成现金。',theoretical='纸')

yc('suzhenmin','苏振民',roles=['阶段性对立者'],bio='苏振民是新式保险箱制造厂的老板，他的目标不是寻找冒险，而是让买家相信自己的产品足够安全。展示会上，他逐项解释防火、防水、抗酸和时间锁，面对年轻人认为任何保险箱都能打开的说法，立即摆出接受挑战的姿态。他很快意识到公开争论可能成为宣传机会，既礼貌又夸张地把产品放在舞台中心。这样一项商业竞争牵动了盗业人物的利益，原本围绕技术的宣传逐渐卷入更复杂的筹谋。苏振民拥有的是生产和销售安全设备的资源，不是保险箱本身的耐久，更不是保证所有操作人员永不失误的魔法。他与叔侄的阶段性对立来自不同目标：他需要确定性的广告，年轻人要证明这种自信存在漏洞。综合演绎应让他能看重证据、担忧品牌和客户财产，也可能为了面子过度承诺；真正的成长空间是把公开挫折转成产品和流程改进，而非每逢登场都重复一句“绝对打不开”。原文没有证明他是贩卖假货或蓄意害人的反派，因此保留商业对手而不是道德恶人的定位。',appearance='头顶半秃的中年男子，面对记者善于微笑和展示。',endpoint='《手套》的保险箱推广与公开挑战人物；没有独立超能力或后续跨书身份。',ability=[A('产品知识与商业展示','理解自家保险箱结构和选配时间锁，以演示吸引客户。',['解释技术条件','组织测试','筹划宣传'],'安全性依赖设备实际结构与人员流程，宣传不能确保绝对不可开启。')],evidence=[E(Y+'01手套.txt',10,29,'身份、设备和挑战反应'),E(Y+'01手套.txt',13,22,'对手观察与宣传判断')],motivation='证明产品价值、维护商业信誉，愿意在可控条件下接受公开挑战。',triggers=[T('公开质疑产品','有记者和客户在场','先澄清具体条件，再安排能复现的演示。'),T('漏洞被证实','继续否认会失去信誉','要求记录过程并修订流程，可能先为面子争辩。'),T('客户把广告当无限担保','实际使用条件不符','具体说明边界，避免含混承诺。')],scores=(1,0,0,1,0,1),limits=(1,2,1),reasoning='技术承诺应能验证，品牌利益容易诱使他把条件省略。',theoretical='纸')

yc('jingang','金刚',roles=['反派'],bio='金刚是掌控庞大犯罪与财富网络的首脑，称号容易让人联想到肉体力量，文本真正展示的却是钱、组织与报复规则。他的集团控制五万以上成员，又雇用高薪专家经营财产；对职业杀手，他用更高报酬购买不利情报，使想雇凶对付他的人反而面临反杀。他也把所网罗的杀手作为生意，而非白养的护卫。奥丽卡收下古堡交易的定金后无法交货，害怕他把失败理解成欺骗，才急迫寻找年轻人帮忙。年轻人不打算正面摧毁这样一个网络，而利用保存的本票和印度老虎的私人仇怨，让两个危险人物彼此碰撞。故事末尾确认双方发生冲突的局势，却没有给出金刚被杀或组织覆灭的结论。综合终局他仍是依赖利益一致维持权势的人，个人拳力与抗性没有因财富增长。他可以计算声誉、背叛成本和报复收益，也会被刻意引导的旧怨牵走注意；演绎中的威胁必须通过真实可用的人手落实。',appearance='个人外观没有足够可核描述，主要以组织首脑身份和威慑名声出现。',endpoint='被年轻人引向与印度老虎正面冲突，胜负未在正文确认。',ability=[A('财富、杀手网络与报复规则','用资金经营情报、雇佣与组织纪律。',['收集威胁信息','委托有限袭击','以合同与定金施压'],'组织需要联络和利益维护；财富不等于个人物理范围或精神控制。')],evidence=[E(Y+'02足球.txt',84,96,'组织、财富、杀手与古堡定金'),E(Y+'02足球.txt',422,434,'被引向冲突的结局')],motivation='维持交易和威慑的可信度，让他人相信欺骗自己代价过高。',triggers=[T('对方未按约交付','怀疑为故意欺骗','核验财物去向并施压，可能把失误当挑战。'),T('雇凶消息出现','提供者可验证','用收益争夺中间人，追溯真正发起者。'),T('私人仇敌被指出','证据正中旧怨','容易优先报复，给第三方转移利益的机会。')],scores=(1,0,1,2,2,3),limits=(2,3,1),reasoning='威慑依赖别人预期，因而容易被以面子与旧怨牵引。',theoretical='并')

yc('indian_tiger','印度老虎',roles=['反派'],bio='印度老虎原本出身土王总管之家，未沿袭父亲职位，而是毒死主人、侵占其家庭与宫殿。事情败露后，他放火逃走，成为以凶暴著称的危险人物。奥丽卡拿他的威胁催迫年轻人，说明他的名声本身就是可被借用的压力；真正见面时，他突出的灰眼与嘶哑吼声又让这种威胁变得可触。年轻人并不与他比谁更狠，而是寻找这位暴躁强者仍无法放下的旧恨。保存两年的本票被交出去后，印度老虎立刻把注意从黄金转到金刚，甚至赶走仍在谈财物的年轻人；情绪优先级被别人看清，便成为行动方向的漏洞。综合终局没有他与金刚冲突后的确切生死，不应替原著安排败亡。参战形态是危险而有经验的人类罪犯，能够使用毒物、纵火和暴力渠道，但不是字面上的猛虎或刀枪不入怪物。他会压迫弱者、追索旧怨，也可能因为暴怒忽略正在发生的资产转移和情报骗局。',appearance='眼睛向外突出、灰色眼珠，吼声高而嘶哑，神情暴虐。',endpoint='把金刚认作长期寻找的目标，转而追索冲突，后果未详。',ability=[A('暴力威慑与阴狠手段','有投毒、纵火与长期犯罪经历，依靠恐惧迫使人服从。',['近身恐吓','组织报复','利用环境制造危险'],'仍是常人血肉；暴怒会改变优先级，没有超自然虎形态。')],evidence=[E(Y+'02足球.txt',136,143,'经历、形貌与威胁'),E(Y+'02足球.txt',422,431,'本票触发旧怨')],motivation='报复旧敌并维护无人敢欺的地位，常把眼前屈服看得比长期收益更重。',triggers=[T('被认为遭到戏弄','对方仍在场','以吼叫和威胁夺回主动，可能失去细节判断。'),T('多年仇敌露出线索','正符合其既有猜想','迅速转向追击，容易忽略验证。'),T('财富与报复同时出现','两者不能兼取','倾向先满足报复，给他人利用空间。')],scores=(3,0,1,2,1,4),limits=(2,1,2),reasoning='靠恐惧维持地位的人，常把克制误作软弱。',theoretical='并')

yc('hunter','亨特',roles=['反派'],bio='亨特是拥有巨大财富的南美人物，也是枪法极好的射手。他与奥丽卡一同找到年轻人藏身处，用远程来福枪制造逼近死亡的威胁；年轻人后来明白，公主看到画像后改变主意，才使这次接触没有成为直接刺杀。亨特的私人关系与政治野心连在一起，他成为奥丽卡的丈夫，也成为筹建南美大印地安帝国计划的重要支柱。财富、武装与熟练枪手的力量看似可以把想象变为现实，却没有解决计划本身的军事风险。年轻人和叔叔设法带走公主后，进攻仍按原计划展开，最终全军覆没，亨特死亡。一个月后，奥丽卡以寡妇身份安葬他，留下的是豪富也无法买掉的失败。恢复参战应明确属于演绎改编，不让他带回已覆灭的整支军队，也不把“枪法神妙”换成无限射程或必定命中。他的行动逻辑可以同时包含亲密关系、控制欲、财富自信与军事判断失误，必要时让他选择撤退，才不至于被固定成再死一次的剧情器械。',appearance='身形高大的西方中年男子，约四十岁，持远程来福枪，姿态自信。',endpoint='帝国进攻计划全军覆没时死亡，奥丽卡以寡妇身份安葬。',deploy='演绎改编：恢复最后可行动形态和终局记忆，配一支有真实弹药的来福枪；军队须另获得。',adapt=[{'change':'恢复死亡前可行动身体，保留军事失败记忆。','reason':'使他能反思或重复自信，而非规定再现同一结局。','power_impact':'不恢复整支军队，不新增命中保证。'}],ability=[A('枪法与资金组织','熟练射击并以财富支持政治军事计划。',['远距火力威慑','组织有限行动','筹措交通装备'],'枪弹与视线条件存在，战略与资源并不确保胜利。')],evidence=[E(Y+'04尺蠖 .txt',75,95,'外形、枪法与来意'),E(Y+'04尺蠖 .txt',995,1009,'计划覆灭与死亡')],motivation='把财富和个人关系转成实际权势，维护自己作为强者的决定权。',triggers=[T('亲密对象要求报复','有清晰射击机会','先按关系意愿行动，显示个人判断受其影响。'),T('进攻出现撤退证据','继续可保面子却损失生命','与终局记忆发生冲突，必须作明确取舍。'),T('财富买不到合作','对方坚持独立','转用威慑或谈判，不能凭钱自动获得服从。')],scores=(2,0,1,2,4,4),limits=(2,2,1),reasoning='个人枪法不能代替对全局的判断，财富也不能取消失败。',theoretical='并')

yc('hans','汉斯',roles=['反派'],bio='汉斯以希特勒的名字公开招摇，使人以为历史上死去的独裁者重现；真正的目标却包含引出一个意大利知情者，追索战争年代被秘密保存的财富。他知道丰城造，却没能轻易分辨眼前身份安排，杀死的朱丰并不是真正的保管者。钱币收藏露面后，多个参与者各凭情报寻找更大宝藏，汉斯把反复回古屋、拷打朱兰和消灭知情者作为推进办法。土耳其皇知道得太多，又与苏联情报当局有联系，最终被他杀害。年轻人的叔叔从线索矛盾辨出汉斯本名及身份骗局，但未能及时阻止死亡。故事后段，汉斯与手下乘豪华游艇离开，船没有抵达目的地，可能遭土耳其皇先前安排的爆炸报复；原文保留了不确定，不能直接断言尸体确认或死后复活。综合终局采用失踪前可行动形态，他的可怕在于利用历史符号与暴力夺财，绝不是希特勒本人拥有的国家军队或超自然归来。',appearance='以欧洲男性身份活动，用名字和历史暗示塑造权威；真实外貌不再补造。',endpoint='与手下乘游艇失踪，死亡未被直接确认，可能涉及预置爆炸。',ability=[A('身份冒用与暴力追财','利用战争内幕、历史假身份和威胁迫使知情者交出财宝线索。',['诱出目标','审讯和杀害阻碍者','掩饰真实姓名'],'需要线索和手下；不能凭冒名继承历史人物资源，仍会误判真假身份。')],evidence=[E(Y+'05大宝藏.txt',989,997,'本名、目标、拷打与杀人'),E(Y+'05大宝藏.txt',1008,1012,'财富欲与失踪')],motivation='取得隐藏财富并灭除泄密风险，认为更多钱能证明与扩大自己的控制。',triggers=[T('历史身份能引出知情者','对方对符号有强烈反应','使用冒名制造轰动，观察谁主动接近。'),T('证人掌握过多内幕','可能把线索交给别人','倾向暴力灭口，暴露更深调查痕迹。'),T('财物已足够富裕','仍有未取的大宝藏','继续冒险追索，忽略退出机会。')],scores=(2,0,1,2,2,3),limits=(2,2,1),reasoning='财富的不断增加不能使其满足，灭口也会使身份伪装出现更多矛盾。',theoretical='并')

yc('shenji_group','神机事件的黑影外星人',aliases=['第七号所属群体'],roles=['反派','阶段性对立者'],bio='这些黑影外星人在地球观察了很长时间，认为人类以不断改进武器的方式加速自毁。他们选择终止部分武器科学家的生命，把谋杀解释成保留文明继续进化的机会。第七号借用达文博士的身体活动，出入既定的空间突破点，像脱去衣服一样离开人体；对地球人来说，这种来去产生鬼影与失踪的传闻。谭宝留下的记录让年轻人和公主看见行动线索，声波破坏又摧毁了房屋及部分证据。公主最终以记忆组进入另一空间，发现对方既真诚认同生命权，又真诚认为杀一个人可救更多人。这一矛盾没有被外星身份自动解决。年轻人要求把发动与使用战争的责任者也纳入判断，末尾独裁者坠机的新闻与之呼应，但具体因果仍由人物推断。综合终局此群体是有目标、有局部空间渠道和高技术杀伤手段的干预者；不能把所有黑影当一位全能神，也不能以宏大慈善目标取消其谋杀行为。',appearance='不规则黑影，可在转换空间时被人眼感到；可借用人类身体。',endpoint='继续在另一空间观察地球，公主完成沟通；第七号与达文肉体是否一同毁灭未确认。',ability=[A('借体、空间节点与技术破坏','在有限突破点转换空间，借人身体行动，以高技术使目标死亡或建筑破碎。',['隐蔽渗透','定点破坏','精神与信息交流'],'节点不是任意地点，个人权限与群体设备区分；研究计划威力不全算现有武器。',kind='外星科技与灵体')],evidence=[E(Y+'06神机.txt',1109,1111,'科学家死亡与不确定肉体结局'),E(Y+'06神机.txt',1165,1167,'借体和节点推断'),E(Y+'06神机.txt',1245,1291,'直接交谈、行动目的与空间限制')],motivation='阻止人类战争技术造成绝灭，却常把具体生命当宏观计算的代价。',triggers=[T('文明研究可大幅增加杀伤','认为会导致集体灭绝','先提出警告与条件，可能升级为定点清除。'),T('被指出责任链不完整','只杀研究者不能停战争','重新分析发令与使用者，不能以旧模型拒绝讨论。'),T('人类成功直接沟通','展示理解与独立判断','解释机制和目的，允许对方质疑。')],scores=(2,5,3,4,4,4),limits=(2,3,1),reasoning='保存进化机会是其自述目的，不等于手段必然正当。',durability='黑影形态与肉身不同，但借来的身体可以毁坏；群体全体不可毁的说法没有依据。',theoretical='狂')

yc('dannier','但尼尔',roles=['主角'],bio='但尼尔是神秘小说作者，喜欢用职业知识解释突发事情，也会在事后把自己写成观察力丰富的人。雾中车祸把想象变成真实，他看见达文博士身体在砖堆下消失，惊恐得无法立即行动，却仍按指示照料昏迷的女乘客，并向警方作证。他的交通事故判断后来得到专家印证，说明恐惧并不抹掉实际观察能力。随着调查深入，他接触秘密住宅与黑影，自己也突然失踪，被带到不同空间或地点，不能再把一切归入普通犯罪。重返人间后，他自嘲写怪事的人竟被真正怪事吓住，也为别人说他想象力不够而耿耿于怀：亲眼所见的黑影反而比小说中的怪物简单。告别公主时，他承诺把她写成下一部小说女主角，把不能掌握的经历重新转换成叙事。综合终局他适合作为会观察、会害怕、也爱加工故事的见证者；不能因小说家身份获得改写现实的权力，也不能把他的修辞直接当精确速度和物理证据。',appearance='成年男性作家，受惊时表情和笑声会显得古怪；具体服饰无须固定。',endpoint='神机事件中失踪后重新出现并离开，决定将公主写入小说。',ability=[A('观察、叙述与常识推理','职业阅读积累使他能分析事故并保留所见，事后加工为故事。',['还原目击细节','辨识叙述矛盾','向他人传达异常'],'恐惧会妨碍行动，修辞不等于测量；没有文字具现或现实改写。')],evidence=[E(Y+'06神机.txt',32,44,'事故判断与恐惧'),E(Y+'06神机.txt',77,90,'救助和作证'),E(Y+'06神机.txt',1066,1094,'归来、黑影与写作选择')],motivation='弄清真正发生的怪事，并把亲历变成可信又有感染力的故事。',triggers=[T('幻想题材成为实物','超出心理准备','先承认害怕，再记录能核对的观察。'),T('目击陈述被质疑','有事实与修辞混合','区分亲见和后来润色，愿修订夸张。'),T('陌生人需要简单救助','没有直接战斗要求','执行具体可做的事，而非强扮英雄。')],scores=(1,0,0,1,0,1),limits=(2,1,1),reasoning='叙事可以整理恐惧，不能替代对事实的核验。',theoretical='纸')

yc('mojie','暗算事件的魔界意志',roles=['反派'],bio='魔界力量通过钻石、空间入口与人心欲望在地球扩大影响，安普女伯爵成为其受控制的代理。它并不只以丑恶面貌恫吓，而以美、权势和旧愿望向对象许诺，使臣服看起来像实现自我的捷径。公主进入卧室后的遭遇与年轻人在门外经历的时间并不直接重合，空间变化让普通追踪失去意义；女伯爵又试图把她拖入更深处。声音宣称希望把魔的意志植入每个人心中，需要公主这样拥有特殊身体的人服务。公主早年做女皇的欲望因此重新强烈，但她和年轻人仍以共同意志反抗，灵魂在特定冲突中脱离肉体并回到人间。魔界没有被证实彻底毁灭，门户未来是否再开仍是忧虑。综合终局此条记录的是该事件可辨识的共同操纵意志，不为每一声恶笑虚构单独恶魔，也不把“正义”或“魔”当全宇宙抽象权柄。它的核心是找出现实裂缝、放大欲望并要求合作，抵抗者仍能用自己的关系和选择破坏诱导。',appearance='主要由声音、变幻感官景象与空间异象呈现，无单一稳定肉体。',endpoint='未能留住年轻人夫妇，女伯爵仍在魔界；门户威胁未彻底解决。',ability=[A('欲望诱导与局部异空间','借媒介和开启的空间作用于进入者，激发欲望并借代理行动。',['制造诱惑','隔离目标','将代理引入异空间'],'依赖入口和接触；不能保证诱惑成功，未显示任意改写所有人的善恶。',kind='精神与空间干涉')],evidence=[E(Y+'07暗算.txt',1177,1196,'媒介、受控与空间变化'),E(Y+'07暗算.txt',1227,1242,'目标、诱惑、抵抗和未解威胁')],motivation='让个体主动接受支配，使自己的意志通过人间行动扩散。',triggers=[T('对象有未满足野心','可建立媒介接触','用看似合理的机会诱导，再逐步提出服从。'),T('目标坚持关系和原则','诱惑没有生效','利用其矛盾加压，而非突然获得无限抹杀权。'),T('代理失去自主性','仍可接近新目标','通过熟悉身份制造入口，暴露代理异常供人识破。')],scores=(1,5,3,4,3,4),limits=(1,4,2),reasoning='它依赖欲望的合作，不能把自称统治一切当已实现事实。',mind='有强烈诱惑与控制实例，也有被抵抗失败；不具必然精神支配。',theoretical='狂')

yc('black_visitors','天敌事件的四名黑衣人',roles=['阶段性对立者','主角'],bio='四名黑衣人以人类难以解释的行动介入太空危机，最初被调查者视作可能的威胁。年轻人和公主循线接触他们，逐步发现真正的灾难并非外星入侵，而是地球国家把核武装进太空船，以及设备失灵可能引发的毁灭。黑衣人展示保留下来的飞船，把地球战争行为当成可供观察的丑恶证据，也让两位地球客人体验自己交通工具的速度。年轻人的身体难以承受，公主的异质身体反应不同，说明这种高速并不自动转成乘客或外星人的所有战斗反应。他们没有接受地球将军对机密的包装，而要求地球人面对相互敌对的后果；最后将年轻人夫妇送回子船，保留危险飞船不再返地。综合终局，他们是带有审判意味的危机干预者，不是确定邪恶的天敌。其技术必须通过飞行器和具体行动呈现，谈话也可能傲慢，但原文没有证明他们可以随意摧毁宇宙或给任何人永久超能力。',appearance='四名穿黑衣的来访者，个体没有稳定个人姓名，行动协调。',endpoint='保留问题飞船并送还年轻人夫妇；地球随后有撤除飞弹新闻。',ability=[A('先进航行与危机处理','以高技术飞行器转移人员、接管危险飞船并展示其状态。',['救援与隔离武器','跨空间或太空交通','提供事实证据'],'需要实际设备；不能将保管核武算作自身能量，具体机体抗性未量化。',kind='外星科技')],evidence=[E(Y+'08天敌.txt',1315,1335,'飞船与武器危机真相'),E(Y+'08天敌.txt',1367,1375,'送回、速度承受与撤弹后果')],motivation='阻止地球人以军备互毁，迫使当事人看见自己的选择。',triggers=[T('武器故障威胁无关生命','可安全接管','隔离危险并保存证据，不以国籍决定救援。'),T('官方要求保密掩盖风险','继续隐瞒会重复事故','把真实状态交给能传达的人。'),T('乘客无法承受交通条件','已有可见身体反应','调整协作和防护，不以技术优越嘲弄脆弱。')],scores=(3,4,3,4,4,4),limits=(2,3,1),reasoning='危机处理的意义在阻止具体毁灭，而不是取得人类统治权。',theoretical='狂')

for key,name,side,other in [('hufeier','胡非尔','美国','考曼'),('kaoman','考曼','苏联','胡非尔')]:
 yc(key,name,roles=['重要配角','阶段性对立者'],bio=f'{name}是{side}军方和太空计划的重要将军，熟悉国家保密体系，也能协调常人无法接近的太空任务。在《天敌》中，他与对立阵营的{other}以及年轻人夫妇共同升空，表面调查异常，实际上必须面对本方太空船携带武器的机密。保密需求使他不能一开始就坦诚说明危险，也让双方把调查者是否可靠放在事实公开之前。年轻人一句玩笑碰中秘密，考曼切断通讯与胡非尔商议，说明这种担心并非空泛口号。最后外星来访者揭露武装与事故，两位将军被告知飞船不会返地，只能将互相敌对导致毁灭的警告带回，各自联络地面返航。后来年轻人仍想到借他们的太空机构渠道推动研究，显示关系没有简单化成永远的敌人。综合终局的{name}保留专业、职权和爱国立场，也保留自己曾参与隐瞒的责任；不把国家核武归为个人随身火力，不预设他能跨国随意下令。他可以在机构纪律与可见灾难之间重新决定公开多少。',appearance=f'成年男性将军，代表{side}太空机构，具体外貌没有必要补造。',endpoint='太空危机后返回本方体系；《消失女神》仍被视为可求助的机构人物。',ability=[A('军方与太空任务协调','以职位、技术渠道和保密知识安排人员与任务。',['申请机构协助','太空通讯协调','风险与情报判断'],'权限受本国组织约束，部队与核武不是本人战力。')],evidence=[E(Y+'08天敌.txt',1368,1375,'保密、返航与后果'),E(Y+'11消失女神.txt',1267,1271,'后续可求助渠道')],motivation=f'维护{side}利益与机密，同时面对危机要求超越阵营合作。',triggers=[T('民间合作者触及机密','不知对方如何得知','先核验来源和可靠性，可能造成不必要隔离。'),T('机密本身造成公共危险','继续隐瞒将扩大后果','与对手共同传回事实，寻求停损。'),T('旧识请求机构资源','任务明确且权限可达','提供正式渠道而非私人包办。')],scores=(1,0,1,2,1,3),limits=(2,3,1),reasoning='制度内的保密习惯不能成为面对灾难时继续欺瞒的理由。',theoretical='并')

yc('feng_rui','冯瑞',roles=['主角','重要配角'],bio='冯瑞是中瑞混血的电脑专家，负责远东大型资料公司中的历史资料部分。他受过良好教育，生活有规律，喜欢体育与音乐，却始终不知道父亲除姓冯、来自中国之外的情况；母亲的强烈悲伤使他不敢继续追问。一次夜归，他遇到自称女巫加加的老妇人，从嘲笑巫术到闻到香味后陷入恍惚，再到参与古代女神与遗迹调查，原有秩序被逐步打破。他能从电传号码认出母亲的住处，使年轻人夫妇与自己的家庭联系浮现，但这些暗示没有形成完整身世答案。后来在神话世界事件中，他用希腊神话知识提出雪伦克丝的解释，给朋友们打开新的调查方向。综合终局他不是因接触异界就成为巫师或有双重血统神力的人，而是能把资料、记忆和好奇心接到现实问题上的年轻专业者。他可以怀疑、犯礼貌上的错，也会修正态度；私人身世的空白应该保留为情感边界，不能由角色卡擅自揭晓。',appearance='不足三十岁的成年男子，身高约一百八十公分，外貌偏中国人，健康俊朗。',endpoint='《神话世界》参与讨论与人物联系，父亲身份与母亲秘密仍未解明。',ability=[A('电脑资料与历史知识','操作大型数据库，记忆联系号码，跨领域检索历史与神话。',['查资料','发现身份联系','提出可验证假设'],'资料范围有界；好奇与神话知识不证明超能力，电脑设备须实际可用。')],evidence=[E(Y+'09夜归.txt',9,23,'职业、家庭与外形'),E(Y+'09夜归.txt',168,185,'电话识别与家族禁区'),E(Y+'09夜归.txt',234,245,'巫术冲突与恍惚'),E(Y+'13神话世界.txt',530,578,'神话解释')],motivation='用知识理解陌生事物，也希望有一天能不伤害母亲地理解自己的身世。',triggers=[T('神秘现象看似荒诞','已有可靠目击或实物','克制嘲笑，寻找可核对的资料。'),T('私人问题使亲人极度痛苦','追问已伤害关系','暂停逼问，保留自己的疑惑与界限。'),T('熟悉信息在陌生案中出现','号码或历史细节吻合','说明联想依据，避免把巧合立刻写成真相。')],scores=(2,0,1,2,1,2),limits=(1,2,1),reasoning='知识能给解释的候选，仍须由事实决定。',theoretical='并')

yc('feng_furen','冯夫人',roles=['重要配角'],bio='冯夫人住在瑞士，是著名细菌学家，也是冯瑞的母亲。她的专业与交际范围很广，能接待年轻人和公主，也能成为他们寻找旧江湖人物的入口。对儿子的父亲，她却几乎不说，只承认姓冯的中国联系；冯瑞一再追问使她极度伤心，家庭中于是形成不可轻触的空白。年轻人夫妇来索线索时，她的语气可以尖刻、突然赶客，也会说彼此应该是自己人，给他们一张足以见到军师的明信片。木盒中保存年轻人叔叔的信，令后辈猜测旧情，但正文没有允许把所有暧昧直接写成已证亲属关系。后来山水被带到瑞士，她又成为接纳这个天才少年、提供研究环境联系的重要人物。综合终局她既不是单纯难伺候的老太太，也不是替所有人解答秘密的资料柜；她有职业能力、旧关系与保护自身伤痛的权利。演绎应让她在提供实际帮助和拒绝私人盘问之间保持可辨选择，而不能把细菌学身份改造成随手释放瘟疫的战斗法师。',appearance='年长女性，在湖畔住所生活；讲话直接尖锐，心事被触及时反应强烈。',endpoint='仍在瑞士生活和研究，接受年轻人夫妇带来的山水；身世旧情未完全揭明。',ability=[A('细菌学与研究联系','具备专业学术能力和研究机构渠道，能提供合适学习环境。',['专业分析','联系研究者','接待和引荐'],'未示可用生物武器；个人保密不等于全知，设备需实验条件。')],evidence=[E(Y+'09夜归.txt',17,18,'职业与家庭'),E(Y+'09夜归.txt',176,185,'隐私与情绪边界'),E(Y+'10四条金龙.txt',1085,1098,'明信片、旧信及未解关系'),E(Y+'11消失女神.txt',1272,1277,'接待山水')],motivation='守住个人历史和独立生活，同时对值得帮助的人提供具体机会。',triggers=[T('晚辈打探亲密旧事','问题触及伤痛','明确拒绝，必要时中断谈话。'),T('来访者有清楚研究需求','确实在能力与渠道范围内','给出联系人或物证，帮助到可执行的一步。'),T('天才少年需要环境','本人有自主选择能力','提供落脚与引荐，不把他当实验标本。')],scores=(1,0,0,1,0,1),limits=(2,2,1),reasoning='愿意帮助不代表必须公开全部私人历史。',theoretical='纸')

yc('jiajia','女巫加加',roles=['主角','阶段性对立者'],bio='女巫加加以瘦削、佝偻而目光锐利的老妇人形象出现在冯瑞的夜归路上。她自称用猫头鹰眼珠保持目力，也直言自己是女巫，让依赖电脑的青年先感到荒谬，随后又被好奇推动靠近。她不靠陌生人的嘲笑决定是否求助，而要请他解释古代女神资料，再带他去看自己掌握的东西。车内香味与恍惚经历使冯瑞怀疑遭到麻醉，醒来时已坐在陌生房间；加加轻描淡写说可能只是疲倦，保留了自己的控制手段。她知道冒险者病毒在墨西哥金字塔中的探索，也能从年轻人与公主的言行看出他们向冯瑞隐瞒了部分事情。综合终局，她是一位拥有遗迹线索、观察力和神秘自我包装的调查推动者，不能因为自称女巫便承认扫帚飞行、咒杀或青春永驻。她的求知与隐瞒并存，提供帮助不取消对同行者自主的侵犯；新场景可让她在保密和取得真实同意之间作出新的选择。',appearance='瘦削佝偻的老妇人，皱纹多、高钩鼻，宽黑衣与黑头布，扶手杖。',endpoint='《夜归》中提供女神与病毒遗迹线索，后续个人结局未详。',ability=[A('遗迹线索与隐蔽接待','掌握旧冒险记录，观察他人反应，并可能以香味影响清醒程度。',['提供历史线索','辨识隐瞒','隐蔽带人至住所'],'麻醉仅为冯瑞合理推测，眼珠保目力为自述；不确认为无条件巫术。')],evidence=[E(Y+'09夜归.txt',55,61,'形貌与接触'),E(Y+'09夜归.txt',215,245,'请求、女巫自称与恍惚'),E(Y+'09夜归.txt',275,284,'麻醉推断'),E(Y+'09夜归.txt',734,741,'观察隐瞒及病毒线索')],motivation='弄清古代女神与遗迹的关系，保住自己掌握的秘密渠道。',triggers=[T('专业者嘲笑神秘身份','仍有实际问题可问','不争名号，直接请其处理具体资料。'),T('同行者追问住所路径','触及保密习惯','解释保密理由或拒绝接待，不自动采用无证据强控。'),T('他人答案有隐藏部分','行为与说法不一致','指出具体矛盾，要求补充。')],scores=(1,1,0,1,0,2),limits=(2,2,1),reasoning='自述与可验证效果必须分开，神秘感不能替代证据。',theoretical='纸')

yc('kangming','康明教授',roles=['主角'],bio='康明教授投入古代文明研究，对金字塔和遗物的意义有执着兴趣。他所面对的难题不是读懂普通碑文，而是隐藏石室、干尸与未知圆片之间的联系；病毒早年的进入既给他留下可能的路径，也把关键物件从原位置带走，使他一度感到自己被耽搁。公主指出，没有先前冒险，他甚至未必能进入，逼他重新认识研究并非单人的功劳。他愿意与年轻人夫妇合作，也会因他们掌握自己不知道的记录而起疑。为寻找想象中的装置，他在金字塔里连续探索数日，疲倦憔悴仍一无所得；真正的突破来自公主花时间感应圆片。听到古代外星战争、女神挽救地球的记录，他既兴奋，又失望于没有直接解开玛亚人失踪之谜。综合终局他保有研究能力和对知识效用的追问，却没有取得外星装置的控制方法。其角色张力在于专注能推动发现，也能让人过度执着原先问题；新的证据需要他调整研究目标，而非自动得到万能学者答案。',appearance='成年男性学者，连续田野搜寻后明显疲倦，等待时会喝酒。',endpoint='知晓圆片记录古代战争和女神救地球，未找到所设想装置，也未解玛亚人去向。',ability=[A('古代遗迹研究','观察石室与文物结构，建立历史解释并组织实地搜寻。',['辨识遗物关联','记录现场','检验学说'],'未知外星记载需适配解读者，教授头衔不等于能操纵遗迹科技。')],evidence=[E(Y+'09夜归.txt',1115,1146,'与病毒记录的关系及疑问'),E(Y+'09夜归.txt',1379,1402,'连续搜寻、记录内容和未解问题')],motivation='把古代遗存转化为可理解的历史知识，解决自己坚持的谜题。',triggers=[T('别人先带走关键物件','研究进度受影响','追问记录与保管，随后承认已有发现的价值。'),T('长期搜寻无果','只有假设没有物证','重新检查问题前提，不凭投入时间宣告成功。'),T('发现与原问题不同','资料仍有独立意义','先保存新证据，再说明哪些谜团仍未解。')],scores=(1,0,0,2,0,1),limits=(1,2,1),reasoning='研究的诚实包含承认未解，不能以神奇发现替代缺失证据。',theoretical='纸')

yc('junshi','冯军师',aliases=['军师','二神堂主人','天涯浪迹客'],roles=['主角','反派'],bio='冯军师年轻时在关外马匪中出谋划策，读过书、字写得好，却把这些能力用来提高勒索效率。他提出烧毁庄稼，使百姓无法承受损失，又以延迟行动和伏击民团扩大武装；同行尚在迟疑时，他直言既做强盗就不该装善男信女。这种清醒并不洗去罪行，反而说明他理解代价仍主动选择。随着势力增长，他希望从流动马匪转为据城自立，潜入黄金屯子谋划绑架乐家孙儿，并与年轻人的叔叔结交。禁地里的异常使他接触隐藏的采金与飞船秘密，当时只能用神仙理解，多年后才重新解释为受伤外星人的机械工厂。晚年他隐居君士坦丁堡，经营二神堂古董店，由女儿冯念慈接待来访者；旧明信片和年叔叔的关系让他愿意重述过去。综合终局采用这个仍能讲述、推理和经营的老人，不把昔日马匪的全套体力原样叠加。他有豪气、贪心和知识自负，也能承认记忆解释随时代改变，不能被一句浪漫江湖抹去烧庄稼的受害者。',appearance='年长中国男子，晚年住古董店楼上；谈起往事兴致高，能写草书。',endpoint='在二神堂隐居，与女儿生活，向年轻人夫妇讲述黄金屯子经历。',ability=[A('谋略、古物与经验复盘','以识人、布局和历史经验策划行动，晚年能经营古物并重新解释旧见闻。',['设计谈判','识别历史线索','组织有限合作'],'晚年体力不等旧日；过去的残酷战术不是自动正确答案，外星设备不归他所有。')],evidence=[E(Y+'10四条金龙.txt',150,185,'纵火、勒索和伏击'),E(Y+'10四条金龙.txt',219,229,'据城与潜入'),E(Y+'10四条金龙.txt',451,451,'姓冯'),E(Y+'10四条金龙.txt',1101,1132,'晚年店铺与女儿'),E(Y+'10四条金龙.txt',1298,1318,'重新解释往事')],motivation='晚年保留独立与朋友情谊，愿理解旧事，但仍有对财富和机缘的复杂心态。',triggers=[T('旧事被赞为浪漫传奇','实际包含具体伤害','说明自己当时做过什么，不能把责任推给时代。'),T('新知识能解释旧异象','记忆与当年说法不合','重述可见细节，明确哪些只是如今推测。'),T('旧友后辈求见','带来可核实关系凭证','有限打开隐居生活，交流后仍保留边界。')],scores=(1,0,1,1,1,4),limits=(2,2,1),reasoning='善谋不等于善人，经验复盘必须保留自己曾主动选择的代价。',theoretical='并')

yc('fangyijia','方一甲',roles=['主角','阶段性对立者'],bio='方一甲在现代已是九十余岁的大富豪，经营人参收购与交易，把罕见野山参用于自己养生，也用于维持权贵关系。他相信人参功效，身体仍好，却没有因此成为不老仙人。年轻人认识他的渠道来自叔叔，两代人再会把旧日关外采参、马匪与黄金屯子的故事重新打开。青年时代的他为营救被截参客收买武装，与年叔叔的江湖立场不完全相同；进入乐家之后，他又为了探听财富秘密，刻意接近两名被父亲禁止出嫁的女子，利用感情试探消息。这使他既是求真参与者，也是会为利益操纵他人的人。几十年后，他仍对军师可能独得好处耿耿于怀，甚至悔恨错过成仙机缘；财富已经极多，遗憾却没有消失。综合终局保留这个有资源、有故事、又被过去未得之物牵住的老人，不能把人参疗效夸成抗枪、再生或无限寿命。新互动可从他愿付高价寻找线索开始，最终逼他区分真的缺失与永远填不满的比较。',appearance='超过九十岁的中国老人，仍健康有精神；富裕身份与昔日贩参经历并存。',endpoint='继续经营并寻找珍稀人参，向年轻人重述往事，仍遗憾黄金屯子机缘。',ability=[A('人参交易与旧江湖情报','依赖收购网、人际关系和记忆辨识线索。',['筹集调查资金','鉴别人参交易','提供旧日证词'],'财富只通过渠道作用；人参没有已证超常防御或永生效果。')],evidence=[E(Y+'10四条金龙.txt',32,43,'年龄、人参与资源'),E(Y+'10四条金龙.txt',482,486,'旧武装营救'),E(Y+'10四条金龙.txt',786,788,'利用感情探秘'),E(Y+'10四条金龙.txt',1012,1039,'怨恨和机缘执念')],motivation='延续健康和财富影响，也想弄清自己错过的秘密。',triggers=[T('有人掌握旧事新证据','涉及自己未得的利益','愿提供资金，但会反复追问别人得到什么。'),T('稀罕物被赋予奇效','事实仍不确定','要求来源和亲历证据，可能受执念诱导高价。'),T('合作需尊重他人感情','不能再以利益借用亲密','面对被揭露的旧手段，选择改用明面条件。')],scores=(1,0,1,1,1,2),limits=(2,3,1),reasoning='已有财富没有消除未得的执念，追问也可能变成重复伤害。',theoretical='纸')

yc('jiaotian','焦田',roles=['反派'],bio='焦田是关外马匪首领，名字来自烧田勒索的恶名，真正出生姓名未明。早期他听军师提出纵火还有迟疑，却在谋划实施后亲自策马喊阵，以精湛骑术避过屯子防守。庄稼焚毁、民团遇袭、枪械被夺，使这支队伍迅速壮大，他逐渐成为威名远播的大队长，也与军师建立生死之交。强盗集团的成功没有让他与军师完全相同：当后者想夺城自立，他更清楚黄金屯子的严密盘查，提醒对方已有队长进去后被杀。他会疑心女人，军师则认为所有人都不可靠，这段对话表露的是以背叛风险组织生活的习惯。综合终局原文没有给出他现代仍生存的确认，部署以历史最后可行动的马匪身体为明确时点选择，不凭空改成九十岁或死后不灭。他有骑术、武器和部众协作经验，却不能因名震千里就拥有千里攻击范围。新场景中，他既可能被军师的大胆说动，也会依据自己见过的防线提出实际异议。',appearance='关外成年马匪，骑术精娴、行动豪强；不凭空指定制服与现代装备。',endpoint='主要存在于《四条金龙》历史回忆，现代个人结局未载。',deploy='以回忆中最后可行动形态入场，保留已叙述经历；部队与马匹需按场景配给。',ability=[A('骑术与马匪指挥','熟练骑乘、武装突袭和野外机动，能与军师配合执行勒索。',['骑乘撤离','战场喊阵','有限部众协同'],'马、枪和部众为实际资源；现代技术环境会改变优势，不能凭声望伤人。')],evidence=[E(Y+'10四条金龙.txt',154,186,'迟疑、骑术、纵火和壮大'),E(Y+'10四条金龙.txt',218,255,'军师关系与对防线判断')],motivation='维持马匪集团的生存、收益和威名，对可靠伙伴有强烈倚重。',triggers=[T('计策要求跨越旧禁忌','收益能壮大集团','先迟疑再衡量执行，不能伪装未懂伤害。'),T('目标防守有已知牺牲','同伴轻视进入风险','提出前车之鉴与替代路径。'),T('军师与常识意见不同','伙伴经历已建立互信','愿听完理由，也保留现场执行判断。')],scores=(3,0,1,3,3,5),limits=(2,3,1),reasoning='义气存在于残酷集团内部，不能抵消对无辜者的勒索。',theoretical='强')

yc('le_laoye','乐老爷',roles=['阶段性对立者','主角'],bio='乐老爷年轻时救助一个从荒野大坑爬出的受伤怪人，后来以对方提供的技术与黄金支撑乐家和黄金屯子的财富。在当时知识里，他把这个来客理解为被贬下凡的神仙，却没有因此永远恭顺；几十年的供养关系也使他觉得对方欠自己。乐家人丁单薄，他珍爱孙儿，同时严密控制家族、保护禁地，甚至不肯让女儿出嫁。军师等人觊觎黄金时，这种封闭既保护秘密，也把家人放进由长辈安排的生活。到怪人需要用金并准备离去，乐老爷追问为什么不给更多，强调凡人需要黄金，又愤怒于对方不念情分。来客警告必须疏散，晚年叙述者却不知道乐家最终是否听从，也不知道整个屯子消失的确切过程。综合终局停在这一分歧，不擅自写成全族死于辐射。他没有亲自操纵地下工厂的证据，真正能力是家族控制、财富分配和长久交涉；新场景要保留救人恩情如何变成占有要求的矛盾。',appearance='年老中国家长，须眉明显，严寒中胡须结冰；家中地位极高。',endpoint='最后已证行动是向受伤来客索金并反对其离去，疏散与生死未有结论。',ability=[A('家族与资源掌控','依靠乐家地位、守卫和财富管理封闭社区。',['保守核心秘密','安排交涉','动员家人和家产'],'黄金来源依赖外星来客，不会制造黄金或默认操纵工厂。')],evidence=[E(Y+'10四条金龙.txt',283,283,'孙儿与家族结构'),E(Y+'10四条金龙.txt',786,788,'控制女儿婚事'),E(Y+'10四条金龙.txt',1236,1256,'索金、恩情和冲突'),E(Y+'10四条金龙.txt',1304,1314,'受伤来客与未知疏散')],motivation='延续家族财富与控制，认为长期恩情应换得持续回报。',triggers=[T('曾受助者想离开','离开会终止资源','强调过去付出并试图挽留，可能拒绝现实风险。'),T('秘密被外人窥探','涉及家族根本利益','加强盘查与谈判，不凭空拥有异星监控。'),T('撤离与财富冲突','继续停留有明确危险','必须在保人和保产之间作可见选择。')],scores=(1,0,1,1,1,2),limits=(2,3,1),reasoning='救助的恩情不能自动变为终身占有，但他常如此理解关系。',theoretical='纸')

yc('gold_alien','黄金屯子的受伤来客',roles=['主角','阶段性对立者'],bio='这个来客没有向叙述者留下可核实的本名，早年在极北荒野受重伤，被少年时代的乐老爷救助。此后六十余年，他留在乐家封闭的禁地，使用地下机械设施取用金矿，使人们以四条金龙和神仙传说解释眼前财富。军师看到的工厂和人影，多年后被理解为先进熔炼与机械操作，但这是事后解释，不能把每一项技术细节当已验证说明书。来客自身一直行动不便，所需黄金也与修复和离开有关，未曾把无限财富作为对乐家的义务。准备离去时，他要求人们疏散，可能因为飞船启动会产生危险辐射；乐家却把离开视作忘恩，矛盾从技术问题变成彼此对关系的不同理解。整个黄金屯子后来消失，军师没有再见乐家人，无法确定是否安全撤离。综合终局采用最后可行动但有旧伤的外星技术者，不自动治愈或补写归乡成功。他可以耐心解释条件，也会因人类永不满足而困惑，不能被写成随叫随到的许愿神。',appearance='受伤后长期行动不便的异星来客，被旧日见证者称怪人或神仙；具体物种不详。',endpoint='准备修复航行并要求疏散，后来是否离地及居民结局未确认。',ability=[A('矿业机械与航行修复','运用先进机械采炼黄金，长期修复航行条件。',['处理矿物','修复设备','危险前安排疏散'],'需要矿藏、工厂与材料，身体仍有旧伤；不是无中生金或许愿权柄。',kind='外星科技')],evidence=[E(Y+'10四条金龙.txt',1236,1256,'黄金用途与离开争执'),E(Y+'10四条金龙.txt',1304,1314,'旧伤、工厂及疏散推论')],motivation='完成修复、返回自己的世界，并摆脱被无穷财富要求拖住的处境。',triggers=[T('受助关系变成无限索取','对方忽略资源用途','说明修复需要和可给上限，拒绝无尽追加。'),T('设备启动危及居民','能预先发出警告','把疏散条件说清，不能宣称危害一定已避免。'),T('被当作神仙','称谓阻碍技术沟通','改用可观察效果说明，不默认理解宗教期待。')],scores=(1,2,2,2,2,2),limits=(2,4,1),reasoning='技术差距不能填平双方对恩情和资源的误解。',durability='长期重伤未愈，不能因为外星身份推为高耐久。',theoretical='并',confidence='low',uncertainties=['身份、机械工厂和起飞辐射多由晚年人物推断；没有确证毁灭村庄或成功归乡。'])

yc('inoue','井上恭二',roles=['主角'],bio='井上恭二出身四国小农家庭，作为次子没有土地继承机会，早早到东京寻找前途。他适应城市很快，外貌俊朗，却缺少能让野心立即实现的资本。与川崎信子相识后，两人共同抓住机会，他用她积蓄在报纸刊登自己的商业构想，发展出大世界集团，成为永远董事长。成功没有消除他对妻子的依恋，为求一只罕见翠玉镯，他愿与黎文祥谈条件，亲赴风险不明的宝藏运输；同时他也坚持必须知道基本路线与联系人，不肯仅因利益任人蒙蔽。这次行动带出镶宝象牙、古代女神与青龙的线索，使商业收藏卷入他无法独自理解的世界。他愿向年轻人夫妇详细叙述过程、提供接待和交通，也会因话题太神奇而只好装作听懂。综合终局，他是有成就的经营者和有感情的伴侣，不是能用财富购买一切真相的救世主。野心可以促使他冒险，关系也可以使他愿意承认自己不懂并求助。',appearance='高大俊朗的日本成年男子，中年仍具活力，讲话会积极推销自己的构想。',endpoint='参与象牙调查后协助年轻人等人，集团和与信子的关系持续。',ability=[A('商业组织与谈判','以构想、宣传、代理网络和资金组织大型交易。',['筹措运输','拍卖与估价交涉','接待专家'],'需组织资源与合法通行条件；超常遗物须外人解读，不能买来其能力。')],evidence=[E(Y+'11消失女神.txt',2,28,'出身与创业'),E(Y+'11消失女神.txt',279,300,'黎文祥交易'),E(Y+'11消失女神.txt',362,378,'风险条件与路线'),E(Y+'11消失女神.txt',1259,1272,'协助与后续')],motivation='经营事业、回报与妻子的关系，并把新机会变成真实成果。',triggers=[T('珍物能让伴侣快乐','来源有风险','愿投入资源，但要求交代实际取得条件。'),T('合作方拒绝基本信息','危险无法衡量','坚持路线与负责人说明，宁可暂停。'),T('事件超出商业知识','已有更合适专家','提供后勤并坦承不懂，不抢解释权。')],scores=(2,0,1,2,1,3),limits=(2,3,1),reasoning='商业勇气需要条件透明，关系比炫耀财力更有持续意义。',theoretical='并')

yc('nobuko','川崎信子',roles=['主角'],bio='川崎信子在认识井上恭二前已经营规模可观的酒吧，年轻时便在复杂社交环境中取得自己的收入和地位。她与恭二的关系不是富豪成功后附带出现的装饰：最初广告资金来自她的积蓄，她愿意相信他的构想，使创业有了实际起点。后来成为他的妻子，两人共同出行、共同参与收藏与交涉，一只她喜欢的翠玉镯让恭二进入黎文祥的宝藏交易，也把他们带到超出商业常识的异常事件中。她会享受美物和丈夫的用心，也会在听不懂危险政治话题时感到尴尬，不能被写成永远事事懂得的幕后智囊。与年轻人、公主来往，她愿意提供帮助，却又坦诚怀疑自己究竟能贡献什么；公主对两人关系的赞赏让她由衷高兴。综合终局保留她有过独立经营、敢投入资源且重视亲密的人生，而不把其外貌和旧行业当全部人格。她能讨论预算、察觉交往气氛，也需要明确知道一件礼物背后是否让别人承担了危险。',appearance='成熟美丽的日本成年女性，仪态有社交经验，佩戴罕见翠玉镯。',endpoint='与井上恭二持续共同生活，参与接待和象牙调查的后勤。',ability=[A('经营与关系判断','酒吧经营和长期社交经验用于管理、合作与识别气氛。',['协调接待','讨论投入风险','支持共同事业'],'没有超常魅惑；财富和伴侣的集团资源须共同协商。')],evidence=[E(Y+'11消失女神.txt',2,53,'创业资金与既有事业'),E(Y+'11消失女神.txt',646,660,'交涉尴尬、玉镯与关系'),E(Y+'11消失女神.txt',1259,1272,'协助和后续')],motivation='维持共同事业与亲密生活，让付出得到真实理解。',triggers=[T('伴侣提出大胆计划','可共同承担风险','问清投入与后果，支持具体可做的第一步。'),T('礼物牵涉不明危险','只有结果被展示','要求说明获得过程，不只欣赏价值。'),T('专家讨论超出经验','自己仍能提供条件','承认不懂并安排接待、时间或沟通。')],scores=(1,0,1,2,1,2),limits=(1,2,1),reasoning='支持伴侣不等于放弃知情，自己的经营经历同样有价值。',theoretical='并')

yc('liwenxiang','黎文祥',roles=['阶段性对立者'],bio='黎文祥从越南来到香港，带着黄金与古文物建立交易入口。他外表穿金戴银，未必符合买家想象中的难民形象，谈判时却能看出别人真正喜欢什么。面对井上恭二，他不用立即兑现的高价出售翠玉镯，而以放弃珍物换取更大宝藏的运输和拍卖，说明他愿意牺牲小额利益构造长链收益。地点必须保密，最后一段甚至要求蒙眼，他把控制信息当合作的重要条件。年轻人夫妇追查象牙时，他又直接表示想借奥丽卡昔日帝国经历学习建立国家的方法，使收藏交易显露出政治野心。夫妇明确拒绝再玩这种游戏，只愿用金钱取得物件，双方因而短暂僵持。综合终局他没有被证实已建立国家或发动成功战争，不可把雄心写成现有统治权；也不因为出身和非法入境便自动认定所有物品来源。可辨的对立在于他试图把别人的欲望接到自己的权力计划上，足以形成新场景中的压力与谈判。',appearance='越南成年男子，西服与贵重饰物，目光有威严，受拒时神情阴沉。',endpoint='未能让年轻人夫妇参与建国野心，继续作为古物与青龙线索的联络人物。',ability=[A('古物交易与利益捆绑','用稀缺宝物、保密地点和联系人组织运输交易，并寻求政治协助。',['引导谈判','安排隐秘路线','交换人脉'],'没有已成国家或无限武装，买家的欲望也可能因代价过高而停止。')],evidence=[E(Y+'11消失女神.txt',279,300,'身份与交易'),E(Y+'11消失女神.txt',332,378,'以小换大与保密'),E(Y+'11消失女神.txt',635,660,'建国目的和拒绝')],motivation='把古物财富与冒险者能力转化成自己的政治事业。',triggers=[T('买家极想取得物件','能换取更大行动','提出捆绑条件并保留关键地点。'),T('合作者要求透明','否则将拒绝','分阶段透露联系人，衡量保密与成交。'),T('政治请求被明确拒绝','对方只愿普通买卖','决定降回交易或放弃，不自动获得其阵营支持。')],scores=(1,0,1,2,1,3),limits=(2,3,1),reasoning='他把珍物当建立权力的工具，交易并非终点。',theoretical='并')

yc('shanshui','山水',roles=['主角'],bio='山水是十四岁的少年，在山沟里长大，由青龙照料和寻找书籍。他不断追问看似简单问题背后的原理，能靠自修阅读五种语言，发表的匿名科学论文使外界怀疑作者是否来自地球之外；他自己却明确说不是外星人。青龙知道普通大学课程已未必满足他，托年轻人夫妇带他去有研究条件的地方，既为他骄傲，又担心自己说话不够有分量。少年面对大人时不只是害羞，会机智回应，也用最普通的语句区分自己引述与判断。到城市后，他把大量时间给图书馆，快速翻阅厚重科学著作，再闭眼沉思，呈现惊人的吸收能力；但这种表现并没有被证实为心灵读取书本或调用前世数据库。去瑞士途中，他仍抱着书看，抵达后自己联系八个机构，展现独立安排学习的能力。综合终局将他定位为非战斗研究型人物，不因天才获得现成武器或成年人所有社会经验；他仍不理解青龙的爱情痛苦，需要尊重、环境与时间。',appearance='瘦弱的东方少年，十四岁，眼神活跃，常携带书籍和笔记。',endpoint='被带到瑞士冯夫人处，并已自行联络研究机构继续学习。',ability=[A('高速学习与基础追问','语言自学、数学和尖端科学理解力极强，能快速阅读整理知识。',['分析技术问题','提出理论','独立联系研究环境'],'没有即看即造任意武器的证据；社会与情感经验仍有限，需设备验证理论。')],evidence=[E(Y+'11消失女神.txt',762,809,'名字、年龄与谈话'),E(Y+'11消失女神.txt',861,883,'自学、论文与非外星自述'),E(Y+'11消失女神.txt',1174,1179,'阅读表现'),E(Y+'11消失女神.txt',1272,1277,'到瑞士与自主联络')],motivation='追索原理并获得能验证自己想法的研究条件。',triggers=[T('答案被说成常识','推导仍有空白','继续问为什么，用纸笔或实验拆开步骤。'),T('成年人以年龄否定','能提出已完成成果','展示论文和推导，争取合适研究环境。'),T('遇到情感问题','不是知识题而是个人经历','承认不懂，倾听而不强行给公式。')],scores=(1,0,0,1,0,1),limits=(1,3,1),reasoning='高智力表现需要验证环境，不意味着在任何领域都成熟。',theoretical='纸')

yc('syrinx','雪伦克丝',aliases=['孙夫人'],roles=['主角','阶段性对立者'],bio='雪伦克丝从神话世界来到人间，以孙夫人的身份生活，目的是逃避潘的追逐与欺凌。她是自然女神，却在人间失去原有能力，既害怕回去，也无法自在留在陌生世界，只能反复靠近连接装置。年轻人误入神话后，公主要求她说明返程入口，她担心潘会循迹发现自己而拒绝，甚至把帮助别人回来当成先替自己除去威胁的条件。这个选择说明受害经历不能自动使一个人对他人无私，也不能成为旁人替她承受一切风险的义务。公主尝试让她相信既然已离开既定故事，命运就能改变，她一度露出希望，却仍不敢自己对抗。最后她答应照看夫妇留在人间的身体，具体是否重返神话、是否恢复神力没有在结尾交代。综合终局采用人间失能形态，保留对装置的知识和强烈求安全欲望，不从希腊神话百科引进额外神权。新互动能让她小步承担合作责任，但不能把“胆怯”当她理应受侵害的理由。',appearance='颀长美丽的成年女性，以黑衣孙夫人形象在人间活动，恐惧时明显退缩。',endpoint='留在人间照顾夫妇身体，返乡及恢复神话能力未确认。',ability=[A('神话入口知识','知道连接人间与神话的装置，自己可整体来去，并能理解离体差异。',['指明入口','照看留置身体','解释局部通行条件'],'在人间自述所有原有能力消失；不自动拥有全领域变形、永生或叙事改写权。',kind='空间接口知识')],evidence=[E(Y+'13神话世界.txt',932,958,'不同通行条件与人间失能'),E(Y+'13神话世界.txt',972,1008,'改变命运的讨论、条件与照看承诺')],motivation='获得不受潘追逐的安全生活，同时逐步学会不把安全代价全部转给他人。',triggers=[T('透露出口可能引来追赶者','恐惧仍有具体根据','先提出隔离和保密条件，避免无限扣留他人。'),T('被要求直接对抗强者','能力当前不足','承认害怕，选择能完成的小范围协作。'),T('合作者托付身体','离体者无法自护','按承诺守护并及时呼唤，不以失败为借口抛弃。')],scores=(1,0,1,1,1,1),limits=(3,3,2),reasoning='受害者有权求安全，也须尊重合作对象的生命与退出。',theoretical='纸',ooc=['不得把恐惧当作应遭欺凌的理由。','不得将讨论“改写神话”升级为可修改作者或现实叙事。'])

yc('pan','潘',roles=['反派'],bio='潘在这部小说的神话空间中是骄纵的强者，嗜酒、暴躁，借众神与宙斯的支持欺凌其他女神。年轻人与他打赌时，看见女神披青草圆毯伏在岩石上，只为使他喝酒时地面悦目；他一跺脚，众女神就惊飞求恕。这种权威既含真实异能，也依赖受害者习惯性的恐惧。潘因答不出年轻人身份而发怒，召起狂风、乌云和冰雹，却连对方遮头的陶罐也未打破，场面比实际伤害更惊人。他遇到公主不低头，又被她提及赫拉的说法牵制，显露自己同样畏惧更高地位。最后被激将与公主一同进入迷宫，公主利用灵魂投影和特殊身体条件脱出，他未再出现，困居结果没有进一步说明。综合终局不导入古典神话中所有潘的权能，也不把地方性的神话规则写成现实宇宙绝对法则。参战若离开迷宫须明确改编，他仍会以声势压人，却可以被规则、赌约、无知与面子共同制约。',appearance='羊须、短羊角、满脸皱纹，声音似牛吼，发怒脸红，形态非普通人。',endpoint='被公主诱入神话迷宫，公主离开而他后续未见。',deploy='演绎改编：允许从最后可行动的迷宫入口状态投放，仍仅具正文表现；不宣称原作已逃出。',adapt=[{'change':'将被困前的行动形态投放新场景，保留被骗记忆。','reason':'使其能参战而不抹去迷宫结局。','power_impact':'不新增跨世界通行或破解迷宫能力。'}],ability=[A('威压、天气异象与旋风移动','在神话空间以吼叫顿足激起风云冰雹、震动与旋风搬运。',['威慑','局部环境扰动','卷带近旁对象移动'],'冰雹未破陶罐；对外来人投影威压有限，受赌约和神话内部地位约束。',kind='局部神话异能')],evidence=[E(Y+'13神话世界.txt',1155,1184,'威压、弱于场面的伤害与赌约'),E(Y+'13神话世界.txt',1208,1222,'公主抵抗及赫拉牵制'),E(Y+'13神话世界.txt',1243,1264,'投影与入迷宫')],motivation='维护他人对自己的畏惧与尊崇，不能忍受被证明无知或胆怯。',triggers=[T('被问到不知道的事','名望正受挑战','先扩大声势，再可能承认一次败局。'),T('对象不怕威压','外来规则使旧手段失效','追问来历，寻找地位关系而露出自身恐惧。'),T('被公开说不敢','触及面子且有观众','可能接受不利挑战，给对方脱困机会。')],scores=(3,3,2,3,2,3),limits=(3,3,2),reasoning='他的权威部分依赖别人接受神话秩序，无法覆盖不了解的外来者。',mind='能强烈威慑本地女神，无法必然摄伏公主或知道年轻人身份。',theoretical='强')

yc('wei_neighbor','韦先生',roles=['主角'],bio='韦先生是孙夫人同住大厦的住客，原本面对的只是一只遗落在计程车中的皮包。他有司机，也在意体面，初见神秘邻居后想借送回失物结识，又怕意图太明显被保安看轻。孙夫人否认皮包属于自己，使他的好奇从普通交往转成了推理：他猜包内可能有不想让人知道的东西，并以自己的身份与语气影响保安的判断。酒后再回想对方，他把魅力、神秘和未知联系起来，逐步介入本可以交给失物程序解决的事件。这里的勇气与好奇并不纯粹，也混有虚荣和窥探，他既想接近对方，又担心吃闭门羹失去面子。之后由冯瑞等人接手的讨论走向神话身份，韦先生并未因此得到女神的力量或所有谜题的答案。综合终局让他作为现实生活中因细小异常而打开入口的普通人活动；他能提供时间、物件和目击细节，也需要学习把私人猜测与事实分开，尊重邻居拒绝接触的边界。',appearance='生活条件较好的成年男性住客，重视礼貌、体面和他人眼光。',endpoint='皮包与孙夫人事件的开端见证者，未有超常形态变化。',ability=[A('日常观察与交涉','记住失物、出入和邻居反应，能与保安协调。',['提供目击线索','核对失物过程','联系相关人员'],'猜测可能受吸引力与虚荣影响；无专业侦探或超能力证据。')],evidence=[E(Y+'13神话世界.txt',46,108,'失物、动机和推断'),E(Y+'13神话世界.txt',125,138,'体面焦虑与接触选择')],motivation='满足好奇并维持自我体面，逐渐面对窥探与帮助之间的界限。',triggers=[T('失物主人否认所有权','自己确信曾目击','记录经过并寻求合适处理，不自行当作搜查许可。'),T('神秘人物吸引注意','接近动机并不单纯','承认自己的兴趣，接受明确拒绝。'),T('推理被新事实推翻','关系或名誉受到影响','修正陈述，不为面子加造线索。')],scores=(1,0,0,1,0,1),limits=(2,1,1),reasoning='好奇可以启动调查，不能使私人猜想成为证据。',theoretical='纸')

yc('lula','卢拉酋长',roles=['反派','阶段性对立者'],bio='卢拉酋长拥有财富、宫廷与展示收藏的野心，希望建起博物馆来证明自己的地位。他通过哥耶四世与奥丽卡取得伊通古董店珍品，欢迎三人带来的货物，期待馆开之日看伦敦警方震惊的脸色，这明确表明他并非不知来路的普通买家。财富在这里购买的不只是艺术，而是凌驾别人秩序之上的快感。可是年轻人没有真正换走原藏品，送来的仍是哥耶四世制作的赝品，酋长在当时并不知道。他的宏大项目后来又发生变化，博物馆被搁置，转而兴建长距离赛车场，使先前罪案中的人暂时逃过揭穿。综合终局不替原著安排真假当场曝光，也不因为酋长头衔就授予一国全军的随时控制。他是能够提供资金、运输与地盘的买主，兴趣和权势相互推动，又可能迅速转向新项目。新互动可以围绕他需要别人认可的收藏、喜欢看对手出丑的心理，以及专业判断过度依赖受雇者的风险展开。',appearance='富裕成年男性统治者，居宫廷，有迎宾仪式；具体身材容貌未详。',endpoint='古董真伪尚未公开揭穿时放弃博物馆计划，转建赛车场。',ability=[A('高额委托与地方资源','通过财富、交通与收藏计划委托他人取得物件。',['资金支持','安排运输接待','以项目吸引专家'],'外部专家可骗他，兴趣变化会浪费投入；不赋予个人军团级战力。')],evidence=[E(Y+'03宝刀.txt',666,674,'接货、知情与赝品'),E(Y+'04尺蠖 .txt',99,111,'项目转向')],motivation='以稀罕收藏和宏大项目彰显地位，享受让别人惊讶的效果。',triggers=[T('新项目更能引人注意','旧项目尚未验证完成','可能转向投入，留下未处理的问题。'),T('珍品依赖单一权威鉴定','鉴定者又是供货者','在质疑下需要另找独立核验。'),T('对手遵循法律与程序','自己可用财富绕行','倾向资助越界行动，把风险转给执行者。')],scores=(1,0,1,1,1,2),limits=(2,3,1),reasoning='花钱取得物件和真正理解物件是两回事。',theoretical='纸')
